import{_ as t,o,c as i,a5 as d}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.2.7 Two-Factor Authentication (2FA, TOTP)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/spec.md","filePath":"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/spec.md"}'),a={name:"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/spec.md"};function c(n,e,r,s,l,h){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="_3-2-7-two-factor-authentication-2fa-totp" tabindex="-1">3.2.7 Two-Factor Authentication (2FA, TOTP) <a class="header-anchor" href="#_3-2-7-two-factor-authentication-2fa-totp" aria-label="Permalink to &quot;3.2.7 Two-Factor Authentication (2FA, TOTP)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.7</td></tr><tr><td>Feature</td><td>Two-Factor Authentication (2FA, TOTP)</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>Any signed-in USER (setup/confirm/disable); partway-signed-in USER holding a 2FA challenge token (verify)</td></tr><tr><td>Version</td><td>2.5 — 2026-09-25 — BR-86 lockout (5 wrong TOTP codes / 10-min window → 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code>) implemented in <code>AuthServiceImpl.checkTwoFactorAttempt</code>, shared by confirm/disable/verify; BR-86 conflict resolved (code now matches appendix). BR-17 still open.</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user enables or disables two-factor authentication from <code>/security</code> (Security settings page), or when a user who already has it enabled completes the password step (3.2.2) or Google sign-in (3.2.3) and is redirected to <code>/2fa-verify</code> to enter a code from their authenticator app.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> USER — signed in (Bearer access token) when enabling, confirming, or disabling; holding only a short-lived <code>twoFactorToken</code> (no access token) when verifying at sign-in.</li><li><strong>Purpose:</strong> Add a second factor based on RFC 6238 time-based one-time codes, so every sign-in method (password or Google OAuth) requires something the user holds in addition to the password.</li><li><strong>Interface:</strong> <code>/security</code> page — &quot;Enable 2FA&quot; action revealing a QR code (rendered client-side from <code>otpAuthUrl</code>) and a 6-digit code input to confirm; &quot;Disable 2FA&quot; action requiring the current code; <code>/2fa-verify</code> page — a single 6-digit code screen shown during sign-in when the account has 2FA enabled.</li><li><strong>Data Processing:</strong> The system generates a TOTP secret and holds it <em>pending</em> in Redis (not persisted to the user record) until a correct code confirms it; only then is the secret written to <code>users.totp_secret</code> and <code>users.two_factor_enabled</code> set. Verifying a code (confirm/disable/login-verify) always checks it via <code>TotpUtil.verify</code>, RFC 6238 semantics (30s step, ±1-step tolerance), then always calls <code>AuthServiceImpl.checkTwoFactorAttempt(userId, codeValid)</code> (BR-86): a wrong code increments a Redis counter at <code>2fa:attempt:{userId}</code> (TTL 10 minutes, set on the first increment), and the 5th wrong code within that window deletes the counter and throws 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code> instead of 400 <code>TWO_FA_CODE_INVALID</code>; a correct code deletes the counter. The same counter and key are shared across <code>confirmTwoFactor</code>, <code>disableTwoFactor</code>, and <code>verifyTwoFactor</code> for a given user.</li></ul><h2 id="routes-dtos-ground-truth-authcontroller-java-authserviceimpl-java" tabindex="-1">Routes / DTOs (ground truth: <code>AuthController.java</code>, <code>AuthServiceImpl.java</code>) <a class="header-anchor" href="#routes-dtos-ground-truth-authcontroller-java-authserviceimpl-java" aria-label="Permalink to &quot;Routes / DTOs (ground truth: `AuthController.java`, `AuthServiceImpl.java`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Auth</th><th>Request body</th><th>Response</th><th>Notes</th></tr></thead><tbody><tr><td><code>POST /api/v1/auth/2fa/setup</code></td><td>Bearer required</td><td>none</td><td><code>ApiResponse&lt;TwoFactorSetupResponse&gt;</code> 200 — <code>{ otpAuthUrl }</code></td><td><code>otpAuthUrl</code> is an <code>otpauth://</code> provisioning URI for the QR code; the raw secret is never returned.</td></tr><tr><td><code>POST /api/v1/auth/2fa/confirm</code></td><td>Bearer required</td><td><code>TwoFactorConfirmRequest { code }</code></td><td><code>ApiResponse&lt;Void&gt;</code> 200</td><td>Persists <code>totpSecret</code> + <code>twoFactorEnabled=true</code>, deletes the pending Redis key.</td></tr><tr><td><code>POST /api/v1/auth/2fa/disable</code></td><td>Bearer required</td><td><code>TwoFactorConfirmRequest { code }</code></td><td><code>ApiResponse&lt;Void&gt;</code> 200</td><td>Clears <code>twoFactorEnabled</code> and <code>totpSecret</code>.</td></tr><tr><td><code>POST /api/v1/auth/2fa/verify</code></td><td><strong>None</strong> (uses <code>twoFactorToken</code> in body instead)</td><td><code>TwoFactorVerifyRequest { twoFactorToken, code }</code></td><td><code>ApiResponse&lt;LoginResponse&gt;</code> 200</td><td>On success sets the <code>refreshToken</code> HTTP-only cookie exactly like <code>/login</code>, and returns <code>LoginResponse</code> (access token, type, expiry).</td></tr></tbody></table><p><code>login()</code> handoff (FR 3.2.2/3.2.3, for context): if <code>user.isTwoFactorEnabled()</code>, login generates a short-lived <code>twoFactorToken</code> (JWT claim <code>type=2fa</code>) and returns it via <code>LoginResponse.twoFactorChallenge</code> — <strong>no access/refresh token is issued at this step.</strong> The client then calls <code>/2fa/verify</code> to complete sign-in.</p><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Two-Factor Authentication screens (grounded in <code>pages/security/index.tsx</code> and <code>pages/auth/TwoFactorVerifyPage.tsx</code>):</p><ul><li><code>/security</code> — 2FA card with a <code>ShieldCheck</code> icon: <ul><li>Not enabled: &quot;Enable 2FA&quot; button.</li><li>Mid-setup: QR code (<code>QRCodeSVG</code> rendered from <code>otpAuthUrl</code>) plus a 6-digit code input, &quot;Confirm&quot; and &quot;Cancel&quot; actions. No secret text is offered for copying and no recovery codes are shown.</li><li>Enabled: hint text plus a &quot;Disable 2FA&quot; button.</li><li>Confirming disable: 6-digit code input, &quot;Confirm Disable&quot; and &quot;Cancel&quot; actions.</li></ul></li><li><code>/2fa-verify</code> — 6 separate single-digit inputs (auto-advance, paste-fill), a &quot;Verify&quot; submit button, and a &quot;Back to login&quot; link that clears the stored <code>twoFactorToken</code> and returns to <code>/login</code>. Reached only when a <code>twoFactorToken</code> is present (in the URL query or <code>sessionStorage</code>); otherwise the page redirects to <code>/login</code>.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> <code>code</code> (6-digit string) for confirm/disable/verify; <code>twoFactorToken</code> for verify. Setup takes no body — the pending secret is generated entirely by the system.</li><li><strong>Input optional:</strong> none.</li><li><strong>System data:</strong> <code>userId</code>, <code>totpSecret</code>, <code>twoFactorEnabled</code>, the pending secret stored in Redis key <code>2fa:setup:{userId}</code> with a 10-minute TTL, the wrong-attempt counter stored in Redis key <code>2fa:attempt:{userId}</code> with a 10-minute TTL (BR-86), <code>twoFactorToken</code> (JWT, claim <code>type=2fa</code>), <code>lastLoginAt</code>, <code>workspaceId</code> (resolved for the access token on successful verify).</li><li><strong>Output:</strong> <code>otpAuthUrl</code> (setup); nothing (confirm/disable); <code>LoginResponse</code> — access token, token type, expiry, and a <code>refreshToken</code> cookie (verify).</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-15:</strong> TOTP 2FA (RFC 6238): 6-digit code, 30-second step, ±1-step clock tolerance (<code>TotpUtil.verify</code>). Secret is expected to be encrypted at rest and regenerated on disable/re-enable per BA intent; the pending-2FA secret (setup) and the <code>twoFactorToken</code> (login) are both short-lived and effectively single-use (the pending secret is deleted on confirm, the token is not reusable once <code>completeLogin</code> issues real tokens). Recovery codes for a lost device are <strong>(TBD: mechanism)</strong> — not implemented; a user who loses their authenticator app must ask an administrator to disable 2FA on their behalf. <code>setupTwoFactor</code>: 404 <code>USER_NOT_FOUND</code> if the account is missing; 400 <code>TWO_FA_ALREADY_ENABLED</code> if already enabled. <code>confirmTwoFactor</code>: 404 <code>USER_NOT_FOUND</code>; 400 <code>TWO_FA_ALREADY_ENABLED</code> if already enabled; 400 <code>TWO_FA_NOT_ENABLED</code> if no pending secret exists in Redis (missing or expired); 400 <code>TWO_FA_CODE_INVALID</code> on mismatch (pending secret is kept, so the user may retry within the 10-minute window, subject to the BR-86 lockout below). <code>disableTwoFactor</code>: 404 <code>USER_NOT_FOUND</code>; 400 <code>TWO_FA_NOT_ENABLED</code> if not enabled or no stored secret; 400 <code>TWO_FA_CODE_INVALID</code> on mismatch (subject to BR-86).</li><li><strong>BR-86:</strong> Wrong 2FA code is limited to a small number of retries (5 within a 10-minute window, matching the OTP lockout pattern) before further attempts return <code>TWO_FA_TOO_MANY_ATTEMPTS</code>; enforced in <code>AuthServiceImpl.checkTwoFactorAttempt</code>, shared by <code>confirmTwoFactor</code>, <code>disableTwoFactor</code>, and <code>verifyTwoFactor</code>. Mechanics confirmed against code: Redis key <code>2fa:attempt:{userId}</code> (constant <code>TWO_FA_ATTEMPT_PREFIX = &quot;2fa:attempt:&quot;</code>), TTL 10 minutes (set on the first wrong attempt), max attempts <code>OTP_MAX_ATTEMPTS = 5</code> (the same constant used by email/phone OTP lockout). On the 5th wrong code the counter is deleted and the call throws 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code> instead of 400 <code>TWO_FA_CODE_INVALID</code>. Any correct code deletes the counter immediately, resetting the window. This is a per-user counter, not per-request-flow — a wrong attempt on <code>/2fa/confirm</code> and a wrong attempt on <code>/2fa/verify</code> for the same user share the same 5-attempt budget.</li><li><strong>BR-17:</strong> Whether 2FA is mandatory for OWNER/MANAGER roles is <strong>(TBD: team decision)</strong> — not implemented; today 2FA is opt-in for every role and <code>AuthServiceImpl</code> has no role-based enforcement anywhere in the setup/confirm/disable/login flow.</li><li><strong>BR-05 / verify at sign-in:</strong> <code>verifyTwoFactor(twoFactorToken, code)</code> — the token must parse as a valid JWT and carry claim <code>type=2fa</code>, else 401 <code>TWO_FA_TOKEN_INVALID</code>; the subject must resolve to an existing user, else 401 <code>TWO_FA_TOKEN_INVALID</code> (anti-enumeration, mirrors normal login&#39;s generic failure). Account status is checked next (<code>checkStatus</code>): 403 <code>ACCOUNT_SUSPENDED</code> or 403 <code>ACCOUNT_DEACTIVATED</code>. If 2FA was disabled or the secret cleared in the meantime → 400 <code>TWO_FA_NOT_ENABLED</code>. Wrong code → 400 <code>TWO_FA_CODE_INVALID</code>, or 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code> on the 5th wrong code within 10 minutes (BR-86). On success, <code>completeLogin</code> runs exactly as in normal login: <code>lastLoginAt</code> updated, <code>AuditAction.LOGIN</code> recorded, access + refresh tokens issued, refresh cookie set.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>code</code> empty or not a 6-digit number → Display: MSG02 (client-side).</li><li><code>code</code> well-formed but does not match the current time window (±1 step) → 400 <code>TWO_FA_CODE_INVALID</code>, Display: MSG20 (or 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code> if it is the 5th wrong code within 10 minutes for that user — BR-86).</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Signed-in user opens <code>/security</code> and clicks &quot;Enable 2FA&quot;.</li><li><code>POST /2fa/setup</code> — system loads the account, confirms 2FA is not already enabled, generates a TOTP secret via <code>TotpUtil.generateSecret()</code>, stores it pending in Redis (<code>2fa:setup:{userId}</code>, TTL 10 min), and returns <code>otpAuthUrl</code>.</li><li>Client renders the QR code from <code>otpAuthUrl</code>; user scans it with an authenticator app.</li><li>User enters the 6-digit code shown by the app and submits.</li><li><code>POST /2fa/confirm { code }</code> — system re-checks not-already-enabled, reads the pending secret from Redis, verifies the code via <code>TotpUtil.verify</code>; a wrong code is passed to <code>checkTwoFactorAttempt</code> (BR-86: increments <code>2fa:attempt:{userId}</code>, 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code> on the 5th within 10 minutes); on match it clears the attempt counter, persists <code>totpSecret</code> + <code>twoFactorEnabled=true</code>, and deletes the pending-setup Redis key. Toast MSG24.</li><li>On a later sign-in (password 3.2.2 or Google 3.2.3), <code>login()</code> sees <code>user.isTwoFactorEnabled()==true</code>, issues a <code>twoFactorToken</code> (claim <code>type=2fa</code>), and returns it via <code>LoginResponse.twoFactorChallenge</code> — <strong>no access/refresh token yet.</strong> Client redirects to <code>/2fa-verify</code>.</li><li>User enters the code from the app on <code>/2fa-verify</code> and submits.</li><li><code>POST /2fa/verify { twoFactorToken, code }</code> (no Bearer header) — system validates the token, loads the user, checks status, verifies the code (wrong code → <code>checkTwoFactorAttempt</code>, BR-86 lockout after 5 within 10 minutes), and on match calls <code>completeLogin</code>: clears the attempt counter, issues access token + refresh token, sets the refresh cookie, records <code>AuditAction.LOGIN</code>. Toast (auth.twoFactor.successToast).</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: Setup requested for an account that no longer exists → 404 <code>USER_NOT_FOUND</code>. 2.a2: Should not occur for a valid session; treated as a generic error toast.</li><li>2.b1: Setup requested while 2FA is already enabled (BR-15) → 400 <code>TWO_FA_ALREADY_ENABLED</code>. 2.b2: User disables 2FA first (Normal Flow of the disable case) before starting setup again.</li><li>5.a1: Confirm while already enabled (double submit / race) → 400 <code>TWO_FA_ALREADY_ENABLED</code>. 5.a2: No action needed; 2FA is already on.</li><li>5.b1: Confirm with no pending secret — never called setup, or the 10-minute TTL expired → 400 <code>TWO_FA_NOT_ENABLED</code>. 5.b2: User restarts setup to get a fresh QR code.</li><li>5.c1: Confirm with a wrong code (BR-15) → 400 <code>TWO_FA_CODE_INVALID</code>, Display: MSG20; the pending secret is kept so the user can retry within the remaining TTL. 5.c2: User re-enters the code.</li><li>5.d1: Confirm with the 5th wrong code within 10 minutes for the same user (BR-86) → 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code>; the attempt counter resets. 5.d2: User waits for the 10-minute window to lapse (or a correct code on a later attempt after the window resets the counter) before retrying.</li><li>Disable.a1: Disable while 2FA is not enabled, or no secret stored → 400 <code>TWO_FA_NOT_ENABLED</code>. Disable.a2: No action needed; 2FA already off.</li><li>Disable.b1: Disable with a wrong code → 400 <code>TWO_FA_CODE_INVALID</code>, Display: MSG20. Disable.b2: User re-enters the code. On success, toast MSG25.</li><li>Disable.c1: Disable with the 5th wrong code within 10 minutes for the same user (BR-86) → 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code>. Disable.c2: User waits for the window to lapse before retrying.</li><li>8.a1: Verify with an unparseable token, a token missing/mismatching <code>type=2fa</code>, or whose subject no longer resolves to a user (BR-05) → 401 <code>TWO_FA_TOKEN_INVALID</code>, toast MSG22. 8.a2: User is returned to <code>/login</code> to sign in again (client clears the stored <code>twoFactorToken</code>).</li><li>8.b1: Verify against a suspended or deactivated account → 403 <code>ACCOUNT_SUSPENDED</code> / 403 <code>ACCOUNT_DEACTIVATED</code>. 8.b2: User contacts support.</li><li>8.c1: 2FA was disabled between the login step and the verify step → 400 <code>TWO_FA_NOT_ENABLED</code>. 8.c2: The account no longer requires a second factor; user is directed back to sign in normally.</li><li>8.d1: Verify with a wrong code (BR-15) → 400 <code>TWO_FA_CODE_INVALID</code>, Display: MSG20. 8.d2: User re-enters the code from the app.</li><li>8.e1: Verify with the 5th wrong code within 10 minutes for the same user (BR-86) → 429 <code>TWO_FA_TOO_MANY_ATTEMPTS</code>, even though the <code>twoFactorToken</code> itself is still within its own 5-minute JWT expiry. 8.e2: User waits for the 10-minute attempt window to lapse, then signs in again (the <code>twoFactorToken</code> may have expired by then, requiring a fresh password/Google sign-in step).</li><li>Lost authenticator app: no self-service recovery exists (BR-15 TBD). An administrator must disable 2FA on the user&#39;s behalf via direct data access; no dedicated admin endpoint for this exists in <code>AuthController</code>.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>On enabling: <code>totpSecret</code> is stored, <code>twoFactorEnabled=true</code>, and the Redis pending-setup key is deleted; the BR-86 attempt counter is cleared.</li><li>On disabling: <code>totpSecret</code> is cleared and <code>twoFactorEnabled=false</code>; the BR-86 attempt counter is cleared.</li><li>On a successful verify at sign-in: <code>lastLoginAt</code> is updated, an <code>AuditAction.LOGIN</code> row is written, an access token plus refresh token (cookie) are issued — identical to a normal <code>/login</code> completion — and the BR-86 attempt counter is cleared.</li><li>On a wrong code (any of the three flows): the BR-86 attempt counter for that user is incremented; on the 5th wrong code within 10 minutes it is deleted and further calls fail with 429 until the user succeeds or the window naturally expires.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Recovery-code mechanism for lost devices (BR-15, TBD).</li><li>Mandatory 2FA enforcement for OWNER/MANAGER roles (BR-17, TBD).</li><li>Admin-initiated 2FA disable on behalf of a locked-out user (no endpoint exists today).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>Ground truth: <code>AuthController.java</code>, <code>AuthServiceImpl.java</code> (brandhub-business-service, incl. <code>checkTwoFactorAttempt</code> BR-86 lockout added this session); <code>Section5_Requirement_Appendix.md</code> BR-15, BR-17, BR-86, MSG20/22/24/25; <code>pages/security/index.tsx</code>, <code>pages/auth/TwoFactorVerifyPage.tsx</code>, <code>services/authService.ts</code> (brandhub-web-dashboard).</p>',30)])])}const f=t(a,[["render",c]]);export{p as __pageData,f as default};
